/* Smart Buddy feature hubs. Data stays on this browser unless sent to the AI endpoint. */
const featureState=(()=>{try{return JSON.parse(localStorage.getItem('buddy-features-v1')||'{}')}catch{return{}}})();
featureState.todos=Array.isArray(featureState.todos)?featureState.todos:[];
featureState.points=Number(featureState.points)||0;
function saveFeatures(){localStorage.setItem('buddy-features-v1',JSON.stringify(featureState))}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function aiTool(action,payload,status){status.textContent='Buddy đang xử lý…';try{const r=await fetch('/api/tools',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,grade:Number(document.querySelector('#level')?.value||8),ageConfirmed:true,...payload}),signal:AbortSignal.timeout(90000)});let d;try{d=await r.json()}catch{throw Error('Máy chủ trả về dữ liệu không hợp lệ.')}if(!r.ok)throw Error(d.message||'Không thể xử lý yêu cầu.');return d}catch(e){status.textContent=e.name==='TimeoutError'||e.name==='TypeError'?'Mất kết nối hoặc quá thời gian chờ. Hãy kiểm tra mạng rồi thử lại.':e.message;throw e}}
function renderCreator(){content.innerHTML=`<div class="tool-heading"><div><span class="eyebrow">SMART AI STUDIO</span><h1>Biến tài liệu thành buổi ôn tập</h1><p class="muted">Dán nội dung hoặc tải PDF/ảnh rõ nét. Buddy sẽ tạo thẻ, câu hỏi hoặc đề luyện phù hợp khối ${grade}.</p></div><span class="privacy-chip">🔒 Khóa API ở máy chủ</span></div><div class="feature-grid"><section class="panel feature-main"><div class="mode-switch"><button class="chip selected" data-mode="flashcards">Thẻ ghi nhớ</button><button class="chip" data-mode="quiz">Trắc nghiệm</button><button class="chip" data-mode="exam">Đề thi thử</button></div><label for="sourceText"><b>Nội dung bài học hoặc chủ đề</b></label><textarea id="sourceText" maxlength="12000" placeholder="Dán đoạn bài học, hoặc nhập chủ đề như: Hàm số bậc hai, khối ${grade}…"></textarea><label class="upload-zone" for="sourceFile"><span>＋</span><b>Chọn PDF hoặc ảnh bài học</b><small>Tối đa 5 MB · PDF, PNG, JPG, WEBP</small><input id="sourceFile" type="file" accept="application/pdf,image/png,image/jpeg,image/webp"></label><div class="two-fields"><label>Mức giải thích<select id="explainLevel"><option value="student">Dễ hiểu cho học sinh</option><option value="detailed">Chi tiết, đào sâu</option><option value="brief">Tóm tắt trong 3 dòng</option></select></label><label>Số câu<select id="itemCount"><option>5</option><option>10</option><option>15</option></select></label></div><button class="primary wide" id="makeMaterial">Tạo học liệu bằng AI ↗</button><div class="notice" id="toolStatus" role="status">Nội dung chỉ được gửi khi bạn bấm tạo. Không tải tài liệu có thông tin riêng tư.</div></section><section class="panel result-panel"><div class="panel-head"><h2>Kết quả</h2><button class="secondary compact" id="copyResult" disabled>Sao chép</button></div><div id="toolResult" class="empty-result"><span>✦</span><p>Học liệu của bạn sẽ xuất hiện ở đây.</p></div></section></div>`;
 let mode='flashcards',result='';document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(x=>x.classList.toggle('selected',x===b))});$('#copyResult').onclick=()=>navigator.clipboard.writeText(result).then(()=>toast('Đã sao chép học liệu.'));
 $('#makeMaterial').onclick=async()=>{const status=$('#toolStatus'),text=$('#sourceText').value.trim(),file=$('#sourceFile').files[0];if(!text&&!file){status.textContent='Hãy dán nội dung, nhập chủ đề hoặc chọn một tệp.';return}if(file&&file.size>5*1024*1024){status.textContent='Tệp lớn hơn 5 MB. Hãy chọn tệp nhỏ hơn.';return}let fileData=null,fileType=null,fileName=null;if(file){fileData=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(file)});fileType=file.type;fileName=file.name}const button=$('#makeMaterial');button.disabled=true;try{const d=await aiTool('material',{mode,text,fileData,fileType,fileName,explainLevel:$('#explainLevel').value,count:Number($('#itemCount').value)},status);result=d.result;$('#toolResult').className='ai-result';$('#toolResult').textContent=result;$('#copyResult').disabled=false;status.textContent='Đã tạo xong. Hãy đối chiếu lại với tài liệu gốc.';featureState.points+=10;saveFeatures()}catch{}finally{button.disabled=false}}
}
let focusEnd=0,focusTick=null,audioCtx=null,noiseNode=null;
function renderFocusHub(){const groups=[['urgent-important','Gấp & quan trọng','Làm ngay'],['important','Quan trọng, chưa gấp','Lên lịch'],['urgent','Gấp, ít quan trọng','Nhờ hỗ trợ'],['later','Chưa gấp, ít quan trọng','Để sau']];content.innerHTML=`<span class="eyebrow">STUDY FLOW</span><h1>Tập trung vào điều quan trọng</h1><div class="focus-layout"><section class="panel pomodoro"><div class="session-dot">● PHIÊN TẬP TRUNG</div><div id="focusClock">25:00</div><div class="segmented"><button data-min="25" class="selected">25 phút</button><button data-min="5">5 phút nghỉ</button></div><div class="actions"><button class="primary" id="focusStart">Bắt đầu</button><button class="secondary" id="focusReset">Đặt lại</button></div><div class="sound-row"><span>Âm thanh nền</span><button class="sound selected" data-sound="off">Tắt</button><button class="sound" data-sound="rain">Mưa</button><button class="sound" data-sound="ocean">Sóng biển</button><button class="sound" data-sound="lofi">Lofi</button></div></section><section class="panel"><div class="panel-head"><div><h2>Ma trận ưu tiên</h2><p class="muted">Kéo việc giữa các ô để đổi mức ưu tiên.</p></div><button class="primary compact" id="addTodo">＋ Thêm việc</button></div><div class="matrix">${groups.map(g=>`<div class="matrix-cell" data-zone="${g[0]}"><span class="matrix-label">${g[1]} <small>${g[2]}</small></span><div class="todo-zone">${featureState.todos.filter(t=>t.zone===g[0]).map(todoHTML).join('')}</div></div>`).join('')}</div></section></div>`;let minutes=25;document.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>{minutes=Number(b.dataset.min);focusEnd=0;clearInterval(focusTick);$('#focusClock').textContent=String(minutes).padStart(2,'0')+':00';document.querySelectorAll('[data-min]').forEach(x=>x.classList.toggle('selected',x===b))});$('#focusStart').onclick=()=>{if(focusEnd)return;focusEnd=Date.now()+minutes*60000;focusTick=setInterval(updateFocus,1000);updateFocus()};$('#focusReset').onclick=()=>{focusEnd=0;clearInterval(focusTick);$('#focusClock').textContent=String(minutes).padStart(2,'0')+':00'};$('#addTodo').onclick=()=>{const title=prompt('Việc bạn cần làm là gì?');if(title?.trim()){featureState.todos.push({id:Date.now(),title:title.trim().slice(0,80),zone:'urgent-important',done:false});saveFeatures();renderFocusHub()}};bindTodos();document.querySelectorAll('[data-sound]').forEach(b=>b.onclick=()=>{playSound(b.dataset.sound);document.querySelectorAll('[data-sound]').forEach(x=>x.classList.toggle('selected',x===b))})}
function todoHTML(t){return `<article class="todo-item" draggable="true" data-id="${t.id}"><button class="todo-check" aria-label="Hoàn thành">${t.done?'✓':'○'}</button><span class="${t.done?'done':''}">${esc(t.title)}</span><button class="todo-delete" aria-label="Xóa">×</button></article>`}
function bindTodos(){document.querySelectorAll('.todo-item').forEach(el=>{el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.id);el.querySelector('.todo-check').onclick=()=>{const t=featureState.todos.find(x=>x.id==el.dataset.id);t.done=!t.done;if(t.done)featureState.points+=3;saveFeatures();renderFocusHub()};el.querySelector('.todo-delete').onclick=()=>{featureState.todos=featureState.todos.filter(x=>x.id!=el.dataset.id);saveFeatures();renderFocusHub()}});document.querySelectorAll('[data-zone]').forEach(z=>{z.ondragover=e=>e.preventDefault();z.ondrop=e=>{e.preventDefault();const t=featureState.todos.find(x=>x.id==e.dataTransfer.getData('text/plain'));if(t){t.zone=z.dataset.zone;saveFeatures();renderFocusHub()}}})}
function updateFocus(){if(!$('#focusClock'))return;const s=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));$('#focusClock').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');if(!s){clearInterval(focusTick);focusEnd=0;featureState.points+=5;saveFeatures();toast('Hoàn thành phiên tập trung! +5 điểm ✦')}}
function playSound(type){if(audioCtx)audioCtx.close();audioCtx=null;if(type==='off')return;audioCtx=new (window.AudioContext||window.webkitAudioContext)();const gain=audioCtx.createGain();gain.gain.value=type==='lofi'?.035:.09;gain.connect(audioCtx.destination);if(type==='lofi'){[220,261.6,329.6].forEach((f,i)=>{const o=audioCtx.createOscillator();o.type='sine';o.frequency.value=f;o.connect(gain);o.start(audioCtx.currentTime+i*.08)})}else{const buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*2,audioCtx.sampleRate),d=buffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(type==='rain'?.55:Math.sin(i/500));noiseNode=audioCtx.createBufferSource();noiseNode.buffer=buffer;noiseNode.loop=true;const filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=type==='rain'?1800:500;noiseNode.connect(filter).connect(gain);noiseNode.start()}}
function renderVisuals(){content.innerHTML=`<span class="eyebrow">VISUAL LEARNING</span><h1>Nhìn kiến thức theo cách dễ nhớ</h1><div class="feature-grid"><section class="panel"><h2>Tạo sơ đồ tư duy</h2><p class="muted">Nhập một chủ đề, AI sẽ chia thành các nhánh chính.</p><div class="form"><input id="mindTopic" maxlength="200" placeholder="Ví dụ: Quang hợp ở thực vật"><button class="primary" id="mindMake">Tạo sơ đồ</button></div><div id="mindStatus" class="notice">Sơ đồ phù hợp khối ${grade}.</div><div id="mindmap" class="mindmap"><div class="mind-center">Chủ đề của bạn</div></div></section><section class="panel"><div class="panel-head"><h2>Kho công thức nhanh</h2><select id="sheetSubject"><option>Toán</option><option>Vật lý</option><option>Hóa học</option><option>Tiếng Anh</option></select></div><div id="sheetCards" class="sheet-cards"></div></section></div>`;const sheets={Toán:[['Bậc hai','Δ = b² − 4ac'],['Pythagore','a² + b² = c²'],['Lượng giác','sin²x + cos²x = 1']], 'Vật lý':[['Chuyển động','v = s / t'],['Định luật II Newton','F = ma'],['Công suất','P = A / t']], 'Hóa học':[['Số mol','n = m / M'],['Nồng độ mol','Cₘ = n / V'],['Khí lý tưởng','PV = nRT']], 'Tiếng Anh':[['Hiện tại hoàn thành','S + have/has + V3'],['Câu bị động','S + be + V3'],['Điều kiện loại 2','If + past, would + V']]};const drawSheets=()=>$('#sheetCards').innerHTML=sheets[$('#sheetSubject').value].map(x=>`<article><small>${x[0]}</small><b>${x[1]}</b></article>`).join('');$('#sheetSubject').onchange=drawSheets;drawSheets();$('#mindMake').onclick=async()=>{const topic=$('#mindTopic').value.trim(),status=$('#mindStatus');if(!topic){status.textContent='Hãy nhập một chủ đề.';return}try{const d=await aiTool('mindmap',{topic},status);const branches=d.branches||[];$('#mindmap').innerHTML=`<div class="mind-center">${esc(topic)}</div><div class="mind-branches">${branches.map(b=>`<article><b>${esc(b.title)}</b>${(b.items||[]).map(i=>`<span>${esc(i)}</span>`).join('')}</article>`).join('')}</div>`;status.textContent='Đã tạo sơ đồ. Hãy đối chiếu với sách giáo khoa.'}catch{}}}
let roomStream=null;
function renderRoom(){const badges=[['🔥',streak?.current>=3,'Chuỗi 3 ngày'],['✓',featureState.todos.filter(t=>t.done).length>=3,'Hoàn thành 3 việc'],['◷',featureState.points>=20,'Tập trung bền bỉ'],['★',games>=3,'Nhà chinh phục']];content.innerHTML=`<span class="eyebrow">STUDY TOGETHER</span><h1>Phòng học chung & thành tích</h1><div class="feature-grid"><section class="panel"><div class="panel-head"><div><h2>Phòng học của bạn</h2><p class="muted">Cùng đếm giờ, bật camera khi bạn muốn.</p></div><span class="room-code">Mã: HG-${String(new Date().getDate()).padStart(2,'0')}${grade}</span></div><div class="video-stage"><video id="selfVideo" muted playsinline></video><div id="videoEmpty"><span>◎</span><p>Camera đang tắt</p></div></div><div class="actions"><button class="primary" id="cameraToggle">Bật camera</button><button class="secondary" id="micToggle">Mic đang tắt</button><button class="secondary" id="copyRoom">Sao chép lời mời</button></div><div class="notice">Bản phòng học này tạo không gian và đồng hồ chung trên thiết bị. Để gọi nhiều người trực tiếp cần dịch vụ tài khoản và máy chủ thời gian thực.</div></section><section class="panel"><div class="score-hero"><small>ĐIỂM NỖ LỰC</small><strong>${featureState.points}</strong><span>điểm ✦</span></div><h2>Huy hiệu của bạn</h2><div class="badge-grid">${badges.map(b=>`<article class="${b[1]?'earned':''}"><span>${b[0]}</span><b>${b[2]}</b><small>${b[1]?'Đã nhận':'Chưa mở khóa'}</small></article>`).join('')}</div><div class="leaderboard"><h3>Bảng xếp hạng tuần</h3><p><b>1. Bạn</b><span>${featureState.points} điểm</span></p><small>Bảng cá nhân trên thiết bị; chưa công khai tên học sinh.</small></div></section></div>`;$('#copyRoom').onclick=()=>navigator.clipboard.writeText(`Cùng học với mình tại ${location.origin} — phòng HG-${String(new Date().getDate()).padStart(2,'0')}${grade}`).then(()=>toast('Đã sao chép lời mời.'));$('#cameraToggle').onclick=toggleCamera;$('#micToggle').onclick=()=>{if(!roomStream){toast('Hãy bật camera/mic trước.');return}const track=roomStream.getAudioTracks()[0];if(track){track.enabled=!track.enabled;$('#micToggle').textContent=track.enabled?'Tắt mic':'Mic đang tắt'}}}
async function toggleCamera(){const b=$('#cameraToggle');if(roomStream){roomStream.getTracks().forEach(t=>t.stop());roomStream=null;if($('#selfVideo')){$('#selfVideo').srcObject=null;$('#videoEmpty').hidden=false;b.textContent='Bật camera'}return}try{roomStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});$('#selfVideo').srcObject=roomStream;await $('#selfVideo').play();$('#videoEmpty').hidden=true;b.textContent='Tắt camera';roomStream.getAudioTracks().forEach(t=>t.enabled=false)}catch{toast('Không thể mở camera. Hãy kiểm tra quyền của trình duyệt.')}}

// Use official YouTube embeds for Lofi. No audio is copied, trimmed or re-hosted.
const lofiTracks=[
 {id:'jfKfPfyJRdk',url:'https://www.youtube.com/watch?v=jfKfPfyJRdk',title:'Lofi hip hop radio',channel:'Lofi Girl',mood:'Học bài & thư giãn'},
 {id:'gmv54pfxk0Q',url:'https://www.youtube.com/watch?v=gmv54pfxk0Q',title:'24/7 Chilled Beats',channel:'College Music',mood:'Đọc sách & tập trung'}
];
const renderFocusBase=renderFocusHub;
renderFocusHub=function(){
 renderFocusBase();
 const row=document.querySelector('.sound-row');if(!row)return;
 const lofiButton=row.querySelector('[data-sound="lofi"]');if(lofiButton)lofiButton.textContent='Lofi YouTube';
 row.insertAdjacentHTML('beforeend','<button class="sound stop-all" id="stopAllSound">■ Tắt tất cả</button>');
 row.insertAdjacentHTML('afterend',`<section class="lofi-library" id="lofiLibrary" hidden><div class="lofi-head"><div><b>Nhạc Lofi trên YouTube</b><small>Phát từ kênh chính thức · không sao chép âm thanh</small></div><button class="secondary compact" id="closeLofi">Đóng</button></div><div class="lofi-list">${lofiTracks.map((t,i)=>`<button class="lofi-track" data-lofi="${t.id}"><span>${i+1}</span><span><b>${t.title}</b><small>${t.channel} · ${t.mood}</small></span><i>▶</i></button>`).join('')}</div><div class="lofi-player" id="lofiPlayer"><span>Chọn một kênh để bắt đầu nghe</span></div><a class="youtube-note" href="https://www.youtube.com/@LofiGirl" target="_blank" rel="noopener">Mở kênh Lofi Girl trên YouTube ↗</a></section>`);
 if(lofiButton)lofiButton.onclick=()=>{stopGeneratedSound();$('#lofiLibrary').hidden=false;lofiButton.classList.add('selected')};
 $('#closeLofi').onclick=()=>{$('#lofiLibrary').hidden=true};
 $('#stopAllSound').onclick=stopAllSound;
 document.querySelectorAll('[data-lofi]').forEach(b=>b.onclick=()=>playLofi(b.dataset.lofi,b));
};
function stopGeneratedSound(){if(audioCtx){audioCtx.close();audioCtx=null}noiseNode=null;document.querySelectorAll('[data-sound]').forEach(x=>x.classList.remove('selected'))}
function stopAllSound(){stopGeneratedSound();const p=$('#lofiPlayer');if(p)p.innerHTML='<span>Đã tắt âm thanh</span>';document.querySelectorAll('[data-lofi]').forEach(x=>x.classList.remove('playing'));const off=document.querySelector('[data-sound="off"]');if(off)off.classList.add('selected');toast('Đã tắt toàn bộ âm thanh.');}
function playLofi(id,button){const track=lofiTracks.find(t=>t.id===id);if(!track)return;stopGeneratedSound();const p=$('#lofiPlayer');p.innerHTML=`<div class="external-player"><b>${esc(track.title)}</b><span>YouTube không cho phát video này bên trong website.</span><a class="primary" href="${track.url}" target="_blank" rel="noopener">▶ Nghe trên YouTube</a><small>Video mở từ kênh chính thức, không tải lại hoặc sao chép.</small></div>`;document.querySelectorAll('[data-lofi]').forEach(x=>x.classList.toggle('playing',x===button));}
const playSoundBase=playSound;
playSound=function(type){if(type==='lofi'){const library=$('#lofiLibrary');if(library)library.hidden=false;stopGeneratedSound();return}const player=$('#lofiPlayer');if(player)player.innerHTML='<span>Chọn một kênh để bắt đầu nghe</span>';playSoundBase(type)};
